-- Chicken Corn Soup
with new_recipe as (
  insert into public.curated_recipes(slug, name, description, category, cuisine, minutes, servings, taste, status, source)
  values ('chicken-corn-soup', 'Chicken Corn Soup', 'Thick chicken and sweetcorn soup with egg ribbons, served with vinegar and chilli sauce.', 'Snacks', 'Pakistani-Chinese', 35, 4, '{"sweet": 2, "salty": 6, "sour": 2, "spicy": 2}'::jsonb, 'published', 'curated')
  on conflict (slug) do nothing returning id
), lines as (
  insert into public.recipe_ingredients(recipe_id, ingredient_id, position, grams, display)
  select new_recipe.id, v.ingredient_id, v.position, v.grams, v.display from new_recipe, (values
    ((select id from public.ingredients where name = 'Chicken Breast'), 1, 250, '250 g'),
    ((select id from public.ingredients where name = 'Corn (Makai)'), 2, 200, '1 cup kernels'),
    ((select id from public.ingredients where name = 'Eggs'), 3, 50, '1, beaten'),
    ((select id from public.ingredients where name = 'Corn Flour'), 4, 30, '3 tbsp'),
    ((select id from public.ingredients where name = 'Salt'), 5, 6, '1 tsp'),
    ((select id from public.ingredients where name = 'White Pepper'), 6, 2, '1/2 tsp'),
    ((select id from public.ingredients where name = 'Soy Sauce'), 7, 15, '1 tbsp'),
    ((select id from public.ingredients where name = 'Garlic'), 8, 5, '2 cloves'),
    ((select id from public.ingredients where name = 'Vinegar'), 9, 15, 'to serve'),
    ((select id from public.ingredients where name = 'Chilli Sauce'), 10, 15, 'to serve')
  ) as v(ingredient_id, position, grams, display) returning recipe_id
)
insert into public.recipe_steps(recipe_id, position, body)
select new_recipe.id, v.position, v.body from new_recipe, (values
  (1, 'Boil the chicken with garlic in 5 cups of water for 20 minutes; shred the chicken and keep the stock.'),
  (2, 'Add the corn, salt, pepper and soy sauce to the stock and bring to the boil.'),
  (3, 'Stir in the corn flour slurry until the soup thickens.'),
  (4, 'Drizzle in the beaten egg while stirring to form ribbons; add the shredded chicken.'),
  (5, 'Serve with vinegar and chilli sauce.')
) as v(position, body);

